using System.Security.Cryptography;
using JiuMi.Application.WeChatVideo;

namespace JiuMi.Application.Tests;

// Golden vectors generated by an independent canonical ISAAC64 implementation and cross-checked
// against the legacy JiumiTool Rng for the same seeds and 131072-byte length.
public sealed class Isaac64KeyStreamTests
{
    [Theory]
    [InlineData(
        1UL,
        "e19ed5d2ca98af2da7a18d07cab39b52a0ab0232d180af1472b36dcf1af5e46f",
        "cc20fdccf5cfab1c",
        "39d98f5b25cc52f0996f7ef9e1022156cb029901be6a11ebbdd7469c6ffd5839")]
    [InlineData(
        42UL,
        "bbd61fa5105a596a9b3cc89c4acb57baf2469ccfa2bc2790c84d04a408160c5d",
        "c4eaa572096b4f86",
        "6684f1c8b8bc473ce2156c9ca6e1cbb724e5ca7e9c6f6214ab3103f7e8d6a51e")]
    [InlineData(
        18446744073709551615UL,
        "7c38fd3a2e7cd8ad64081892c82430f3a8eca8122a6f4607f6943b85ac39b6f0",
        "ee6bff4658586290",
        "5afbffd76305e81467f97c6370fa07916e9b197611bf5c357a854eb92a6354a1")]
    public void CreateDecryptionArray_GivenSeed_MatchesIndependentReference(
        ulong seed,
        string first32,
        string last8,
        string sha256)
    {
        byte[] stream = new Isaac64KeyStream(seed).CreateDecryptionArray(131072);

        Assert.Equal(131072, stream.Length);
        Assert.Equal(first32, Convert.ToHexString(stream.AsSpan(0, 32)).ToLowerInvariant());
        Assert.Equal(last8, Convert.ToHexString(stream.AsSpan(stream.Length - 8)).ToLowerInvariant());
        Assert.Equal(sha256, Convert.ToHexString(SHA256.HashData(stream)).ToLowerInvariant());
    }

    [Fact]
    public void CreateDecryptionArray_GivenZeroLength_ReturnsEmpty()
    {
        byte[] stream = new Isaac64KeyStream(1).CreateDecryptionArray(0);

        Assert.Empty(stream);
    }
}
